+import { LINEAR_UNITS, TEMPERATURE_UNITS } from "./units.ts";
+
+const ABSOLUTE_ZERO_C = -273.15;
+
+function isTemperature(unit: string): unit is (typeof TEMPERATURE_UNITS)[number] {
+  return (TEMPERATURE_UNITS as readonly string[]).includes(unit);
+}
+
+function isKnown(unit: string): boolean {
+  return isTemperature(unit) || Object.hasOwn(LINEAR_UNITS, unit);
+}
+
+function toCelsius(value: number, unit: (typeof TEMPERATURE_UNITS)[number]): number {
+  switch (unit) {
+    case "C":
+      if (value < ABSOLUTE_ZERO_C) throw new RangeError(`temperature below absolute zero: ${value} C`);
+      return value;
+    case "F":
+      if (value < -459.67) throw new RangeError(`temperature below absolute zero: ${value} F`);
+      return ((value - 32) * 5) / 9;
+    case "K":
+      if (value < 0) throw new RangeError(`temperature below absolute zero: ${value} K`);
+      return value - 273.15;
+  }
+}
+
+function fromCelsius(celsius: number, unit: (typeof TEMPERATURE_UNITS)[number]): number {
+  switch (unit) {
+    case "C":
+      return celsius;
+    case "F":
+      return (celsius * 9) / 5 + 32;
+    case "K":
+      return celsius + 273.15;
+  }
+}
